/* @autogenerated */
package net.civeira.phylax.feature.observe.health;

import org.eclipse.microprofile.health.HealthCheck;
import org.eclipse.microprofile.health.HealthCheckResponse;
import org.eclipse.microprofile.health.HealthCheckResponseBuilder;
import org.eclipse.microprofile.health.Readiness;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;

/**
 * The collector in /q/health/ready: DOWN when the writer is stuck with the queue full; UP with
 * {@code degraded=true} when it drops events or the disk is above 90 % of its limit (the
 * application keeps serving: observing must never take it down).
 */
@Readiness
@ApplicationScoped
@RequiredArgsConstructor
public class ObserveHealthCheck implements HealthCheck {

  private final ObserveHealth health;

  @Override
  public HealthCheckResponse call() {
    ObserveHealth.Status status = health.status();
    HealthCheckResponseBuilder response =
        HealthCheckResponse.named("observability").status(status != ObserveHealth.Status.DOWN);
    health.collector().forEach((key, value) -> {
      if (value instanceof Number number) {
        response.withData(key, number.longValue());
      } else if (null != value) {
        response.withData(key, String.valueOf(value));
      }
    });
    return response.withData("degraded", status == ObserveHealth.Status.DEGRADED).build();
  }
}
